// A 360° panorama a computer generated beyond the edges of a photo, or its 3D version, as the viewers of every device
// read it (design-final 2026-10-27, section 5, lot P4): our packet at the head of its file (PanoramaXmp,
// StereoPanoramaXmp) with Origin GeneratedContent, where the photo itself lies and the quality flags. The panorama
// viewer of the phones, tablets, computers and TVs says "Generated by AI beyond the photo's edges" for a few seconds,
// outlines the photo meanwhile, opens on it and keeps the "360° AI" badge; the share browser of the Quest marks its
// tile with the badge and offers "View the 360° version" from the original. The 3D version of a 360° photo of the user
// (Origin EstimatedDepth) is a relief estimated by AI, nothing invented beyond its edges: "3D AI".
//
// The immersive viewer of the Quest reads the same packet itself, from the head of every photo it shows on a sphere
// (GeneratedPanorama.kt), since previous and next reach photos without new labels: the app hands it the translated
// texts with every opening (see generatedPanoramaViewerLabels), its English texts standing in otherwise.

import 'dart:math' as math;
import 'dart:typed_data';

import 'package:immich_mobile/domain/models/ai_immersive/immersive_format.dart';
import 'package:immich_mobile/domain/models/ai_immersive/immersive_xmp.dart';
import 'package:immich_mobile/domain/models/ai_immersive/stereo_pair_requests.dart';
import 'package:immich_mobile/generated/translations.g.dart';

/// How much of the head of a photo is read for our packet: the window the computers write it within (128 KiB)
const generatedPanoramaHeadLength = 128 * 1024;

/// The key of the immersive viewer's labels for the line of a quality flag of a panorama: this prefix and the flag as
/// written in Immuch360:QualityFlags (GeneratedPanorama.LABEL_FLAG_PREFIX of the headset)
const panoramaFlagLabelPrefix = 'panoramaFlag_';

/// The key of the immersive viewer's labels for "Relief estimated by AI" (StereoComposer.LABEL_RELIEF_ESTIMATED)
const reliefEstimatedLabelKey = 'aiReliefEstimated';

/// What the viewers take from our packet of a panorama: its [kind], its [origin], where the photo itself lies
/// ([region], null for a packet of a newer format, which may place it otherwise, or without it) and its [flags]
class GeneratedPanoramaInfo {
  const GeneratedPanoramaInfo({required this.kind, required this.origin, this.region, this.flags = const []});

  /// The panorama of [xmp], null for a packet of another kind or none
  static GeneratedPanoramaInfo? of(ImmersiveXmp? xmp) => switch (xmp) {
    final PanoramaXmp panorama => GeneratedPanoramaInfo(
      kind: ImmersiveKind.panorama360,
      origin: panorama.origin,
      region: panorama.isNewerFormat ? null : panorama.region,
      flags: panorama.qualityFlags,
    ),
    final StereoPanoramaXmp stereo => GeneratedPanoramaInfo(
      kind: ImmersiveKind.stereoPanorama360,
      origin: stereo.origin,
      region: stereo.isNewerFormat ? null : stereo.region,
      flags: stereo.qualityFlags,
    ),
    _ => null,
  };

  final ImmersiveKind kind;
  final ImmersiveOrigin? origin;
  final PhotoRegion? region;
  final List<ReliefQualityFlag> flags;

  /// Generated by AI beyond the edges of a photo, whatever the version of the packet: the honest side
  bool get isGenerated => origin == ImmersiveOrigin.generatedContent;

  /// The 3D version of a 360° photo of the user: its relief estimated by AI, nothing invented beyond its edges
  bool get isEstimatedRelief => kind == ImmersiveKind.stereoPanorama360 && origin == ImmersiveOrigin.estimatedDepth;

  /// Whether the viewers say anything of it: one of the two above
  bool get isOurs => isGenerated || isEstimatedRelief;

  @override
  bool operator ==(Object other) =>
      other is GeneratedPanoramaInfo &&
      other.kind == kind &&
      other.origin == origin &&
      other.region == region &&
      _sameFlags(other.flags, flags);

  @override
  int get hashCode => Object.hash(kind, origin, region, Object.hashAll(flags));

  @override
  String toString() => 'GeneratedPanoramaInfo(${kind.xmp}, ${origin?.xmp}, $region, ${flags.map((f) => f.xmp)})';
}

bool _sameFlags(List<ReliefQualityFlag> a, List<ReliefQualityFlag> b) {
  if (a.length != b.length) {
    return false;
  }
  for (var i = 0; i < a.length; i++) {
    if (a[i] != b[i]) {
      return false;
    }
  }
  return true;
}

/// Our panorama in [head], the start of a file; null when it holds no packet of ours of a panorama, or one that says
/// nothing (neither generated nor a relief estimated)
GeneratedPanoramaInfo? generatedPanoramaOfHead(Uint8List head) {
  final info = GeneratedPanoramaInfo.of(ImmersiveXmp.findIn(head));
  return info != null && info.isOurs ? info : null;
}

/// A point of the sphere seen from its centre, in degrees: the longitude from the centre column of the panorama,
/// positive to the right, and the latitude, positive upwards (the frame of the panorama viewer)
typedef SpherePoint = ({double longitude, double latitude});

/// The outline of the photo of [region] on its panorama: four arcs, its top, right, bottom and left edges, each from
/// one corner to the next, [segments] + 1 points each. The photo is where pano-v1 put it (make_pano_golden.py, step 1):
/// a pinhole camera looking at the yaw and the pitch of [region], whose plane meets a direction at (a, b), a to the
/// right and b upwards, inside when |a| is at most tan(hfov / 2) and |b| at most tan(vfov / 2). A straight edge of the
/// photo is an arc of a great circle: the top edge of a wide photo bends up towards its middle. PanoramaOutline.kt of
/// the headset draws the same arcs.
List<List<SpherePoint>> photoRegionOutline(PhotoRegion region, {int segments = 32}) {
  final t = math.tan(region.hfov * math.pi / 360);
  final s = math.tan(region.vfov * math.pi / 360);
  final yaw = region.yaw * math.pi / 180;
  final pitch = region.pitch * math.pi / 180;
  // The centre of the photo, the way to its right (along the longitude), the way to its top (along the meridian), in
  // a frame x right, y up, z ahead
  final forward = [math.cos(pitch) * math.sin(yaw), math.sin(pitch), math.cos(pitch) * math.cos(yaw)];
  final right = [math.cos(yaw), 0.0, -math.sin(yaw)];
  final up = [-math.sin(pitch) * math.sin(yaw), math.cos(pitch), -math.sin(pitch) * math.cos(yaw)];
  SpherePoint point(double a, double b) {
    final d = [for (var i = 0; i < 3; i++) forward[i] + a * right[i] + b * up[i]];
    final length = math.sqrt(d[0] * d[0] + d[1] * d[1] + d[2] * d[2]);
    return (
      longitude: math.atan2(d[0], d[2]) * 180 / math.pi,
      latitude: math.asin((d[1] / length).clamp(-1.0, 1.0)) * 180 / math.pi,
    );
  }

  final corners = [(-t, s), (t, s), (t, -s), (-t, -s)];
  return [
    for (var k = 0; k < 4; k++)
      [
        for (var i = 0; i <= segments; i++)
          point(
            corners[k].$1 + (corners[(k + 1) % 4].$1 - corners[k].$1) * i / segments,
            corners[k].$2 + (corners[(k + 1) % 4].$2 - corners[k].$2) * i / segments,
          ),
      ],
  ];
}

/// The line the panel of the headset keeps for a quality flag of a panorama, null for a flag a panorama never raises
String? panoramaFlagText(Translations t, ReliefQualityFlag flag) => switch (flag) {
  ReliefQualityFlag.seam => t.ai_immersive_quality_seam,
  ReliefQualityFlag.mostlyInvented => t.ai_immersive_quality_mostly_invented,
  ReliefQualityFlag.fovGuessed => t.ai_immersive_quality_fov,
  ReliefQualityFlag.hiddenAreas => t.ai_immersive_quality_hidden,
  ReliefQualityFlag.lowRelief => t.ai_immersive_quality_flat,
  _ => null,
};

/// The translated labels of a panorama of ours in the immersive viewer of the Quest, under the keys it reads
/// (GeneratedPanorama.kt): the passing text of a generated panorama (generatedNotice), the caption of the outline of
/// its photo (photoRegion, drawn by the panorama viewer of the other devices: the headset shows the outline alone),
/// "Relief estimated by AI" for the 3D version of a 360° photo, and the line of each quality flag. Sent with every
/// opening, since the viewer finds such a panorama by itself, previous and next included.
Map<String, String> generatedPanoramaViewerLabels(Translations t) => {
  generatedNoticeLabelKey: t.ai_immersive_panorama_honesty,
  photoRegionLabelKey: t.ai_immersive_photo_region,
  reliefEstimatedLabelKey: t.ai_immersive_relief_estimated,
  for (final flag in ReliefQualityFlag.values) '$panoramaFlagLabelPrefix${flag.xmp}': ?panoramaFlagText(t, flag),
};
